class AuthoringError(ValueError):
    """Raised when the supplied bundle is not the sealed review assignment."""


def _sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def _read_json(path: Path) -> dict[str, object]:
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise AuthoringError(f"cannot read {path}: {exc}") from exc
    if not isinstance(value, dict):
        raise AuthoringError(f"{path} is not a JSON object")
    return value


def _read_csv(path: Path) -> list[dict[str, str]]:
    try:
        with path.open(newline="", encoding="utf-8") as handle:
            return list(csv.DictReader(handle))
    except OSError as exc:
        raise AuthoringError(f"cannot read {path}: {exc}") from exc


def _resolve_bundle_file(bundle: Path, relative: str) -> Path:
    candidate = (bundle / relative).resolve()
    try:
        candidate.relative_to(bundle)
    except ValueError as exc:
        raise AuthoringError(
            f"allowed manifest path escapes the supplied bundle: {relative}"
        ) from exc
    return candidate


def _validate_allowed_inputs(
    bundle: Path, manifest: dict[str, object]
) -> None:
    allowed = manifest.get("allowed_inputs")
    if not isinstance(allowed, list):
        raise AuthoringError("allowed manifest lacks allowed_inputs")
    for index, record in enumerate(allowed):
        if not isinstance(record, dict):
            raise AuthoringError(f"allowed input {index} is not an object")
        relative = record.get("path")
        expected_bytes = record.get("bytes")
        expected_sha = record.get("sha256")
        if (
            not isinstance(relative, str)
            or not isinstance(expected_bytes, int)
            or not isinstance(expected_sha, str)
        ):
            raise AuthoringError(f"allowed input {index} has malformed metadata")
        path = _resolve_bundle_file(bundle, relative)
        try:
            payload = path.read_bytes()
        except OSError as exc:
            raise AuthoringError(f"cannot read sealed input {relative}: {exc}") from exc
        if len(payload) != expected_bytes or _sha256(payload) != expected_sha:
            raise AuthoringError(f"sealed input differs from manifest: {relative}")


def _validate_projection(
    accepted_rows: object,
    input_rows: list[dict[str, str]],
    immutable_fields: tuple[str, ...],
    label: str,
) -> None:
    if not isinstance(accepted_rows, list) or len(accepted_rows) != len(input_rows):
        raise AuthoringError(f"{label} row count differs from sealed projection")
    for index, (accepted, source) in enumerate(zip(accepted_rows, input_rows)):
        if not isinstance(accepted, dict):
            raise AuthoringError(f"{label} row {index} is not an object")
        for field in immutable_fields:
            if accepted.get(field) != source.get(field):
                raise AuthoringError(
                    f"{label} row {index} changes immutable field {field}"
                )


def _accepted_output(bundle: Path) -> bytes:
    manifest_path = bundle / "allowed-manifest.json"
    try:
        manifest_bytes = manifest_path.read_bytes()
    except OSError as exc:
        raise AuthoringError(f"cannot read {manifest_path}: {exc}") from exc
    if _sha256(manifest_bytes) != EXPECTED_ALLOWED_MANIFEST_SHA256:
        raise AuthoringError("supplied bundle has an unexpected allowed manifest")
    manifest = _read_json(manifest_path)
    for field, expected in EXPECTED_MANIFEST.items():
        if manifest.get(field) != expected:
            raise AuthoringError(
                f"supplied bundle manifest field {field} differs from assignment"
            )
    _validate_allowed_inputs(bundle, manifest)

    try:
        output_bytes = zlib.decompress(base64.b85decode(PAYLOAD_B85.encode("ascii")))
    except (ValueError, zlib.error) as exc:
        raise AuthoringError(f"embedded accepted output is corrupt: {exc}") from exc
    if _sha256(output_bytes) != EXPECTED_OUTPUT_SHA256:
        raise AuthoringError("embedded accepted output hash differs")
    try:
        output = json.loads(output_bytes)
    except json.JSONDecodeError as exc:
        raise AuthoringError(f"embedded accepted output is invalid JSON: {exc}") from exc
    if not isinstance(output, dict):
        raise AuthoringError("embedded accepted output is not an object")

    expected_metadata = {
        "worker_id": manifest["worker_id"],
        "bundle_sha256": manifest["content_set_sha256"],
        "prompt_sha256": manifest["prompt_sha256"],
        "schema_sha256": manifest["schema_sha256"],
        "allowed_manifest_sha256": EXPECTED_ALLOWED_MANIFEST_SHA256,
        "prohibited_input_nonuse": True,
    }
    for field, expected in expected_metadata.items():
        if output.get(field) != expected:
            raise AuthoringError(f"accepted output metadata differs at {field}")

    reading_input = _read_csv(bundle / "input" / "reading-input.csv")
    asset_input = _read_csv(bundle / "input" / "asset-input.csv")
    _validate_projection(
        output.get("reading_updates"),
        reading_input,
        READING_IMMUTABLE_FIELDS,
        "reading",
    )
    _validate_projection(
        output.get("asset_updates"),
        asset_input,
        ASSET_IMMUTABLE_FIELDS,
        "asset",
    )
    return output_bytes


def _write_atomic(path: Path, payload: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(f".{path.name}.{os.getpid()}.tmp")
    try:
        temporary.write_bytes(payload)
        os.replace(temporary, path)
    finally:
        try:
            temporary.unlink()
        except FileNotFoundError:
            pass


def main() -> int:
    parser = argparse.ArgumentParser(
        description="Author the accepted Stage 12 chapter-8 Notes blind review."
    )
    parser.add_argument(
        "--bundle",
        type=Path,
        required=True,
        help="sealed ch08-notes worker bundle",
    )
    parser.add_argument(
        "--output",
        type=Path,
        help="destination JSON (default: BUNDLE/output/output.json)",
    )
    args = parser.parse_args()
    bundle = args.bundle.resolve()
    output_path = (
        args.output.resolve()
        if args.output is not None
        else bundle / "output" / "output.json"
    )
    try:
        payload = _accepted_output(bundle)
        _write_atomic(output_path, payload)
    except AuthoringError as exc:
        print(f"authoring failed: {exc}", file=sys.stderr)
        return 1
    parsed = json.loads(payload)
    print(
        "authored ch08-notes review "
        f"sha256={_sha256(payload)} "
        f"readings={len(parsed['reading_updates'])} "
        f"candidates={len(parsed['candidate_proposals'])} "
        f"assets={len(parsed['asset_updates'])} "
        f"routes={len(parsed['route_proposals'])} "
        f"output={output_path}"
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
